/// Resolve a lexicon `species` key (`ANIMAL_GLYPHS[i].id`) to its roster id.
/// Linear over a few dozen species; called at rescan, not per frame.
#[must_use]
pub fn animal_glyph_from_key(key: &str) -> Option<AnimalGlyphId> {
    ANIMAL_GLYPHS
        .iter()
        .position(|g| g.id == key)
        .map(|i| ANIMAL_GLYPH_IDS[i])
}
